// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title IoTDeviceFirmwareRegistry
 * @notice Manages firmware update scheduling for IoT devices with async confirmation
 * @dev Uses a two-phase commit pattern for firmware deployments
 */
contract IoTDeviceFirmwareRegistry {
    struct DeviceState {
        uint256 firmwareVersion;
        uint256 pendingVersion;
        uint256 lastHeartbeat;
        uint256 updateWindowStart;
        uint256 updateWindowDuration;
        uint8 retryCount;
        bool awaitingConfirmation;
    }

    struct FirmwareMetadata {
        bytes32 checksum;
        uint256 minVersion;
        uint256 maxDevices;
        uint256 deployedCount;
        uint256 rollbackGracePeriod;
    }

    mapping(address => DeviceState) public devices;
    mapping(uint256 => FirmwareMetadata) public firmwares;
    mapping(address => mapping(uint256 => uint256)) public deviceUpdateTimestamps;

    address public admin;
    uint256 public globalUpdateCooldown;
    uint256 constant MAX_RETRY = 3;
    uint256 constant HEARTBEAT_TIMEOUT = 1 hours;
    uint256 constant MIN_WINDOW_DURATION = 5 minutes;

    event FirmwareScheduled(address indexed device, uint256 version);
    event FirmwareConfirmed(address indexed device, uint256 version);
    event FirmwareRolledBack(address indexed device, uint256 fromVersion, uint256 toVersion);
    event DeviceHeartbeat(address indexed device, uint256 timestamp);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyRegisteredDevice() {
        require(devices[msg.sender].firmwareVersion > 0, "Device not registered");
        _;
    }

    constructor(uint256 _cooldown) {
        admin = msg.sender;
        globalUpdateCooldown = _cooldown;
    }

    function registerDevice(address device, uint256 initialVersion) external onlyAdmin {
        require(devices[device].firmwareVersion == 0, "Already registered");
        require(initialVersion > 0, "Invalid version");
        devices[device] = DeviceState({
            firmwareVersion: initialVersion,
            pendingVersion: 0,
            lastHeartbeat: block.timestamp,
            updateWindowStart: 0,
            updateWindowDuration: 0,
            retryCount: 0,
            awaitingConfirmation: false
        });
    }

    function registerFirmware(
        uint256 version,
        bytes32 checksum,
        uint256 minVersion,
        uint256 maxDevices,
        uint256 rollbackGracePeriod
    ) external onlyAdmin {
        require(firmwares[version].checksum == bytes32(0), "Already registered");
        firmwares[version] = FirmwareMetadata({
            checksum: checksum,
            minVersion: minVersion,
            maxDevices: maxDevices,
            deployedCount: 0,
            rollbackGracePeriod: rollbackGracePeriod
        });
    }

    function scheduleUpdate(
        address device,
        uint256 targetVersion,
        uint256 windowStart,
        uint256 windowDuration
    ) external onlyAdmin {
        DeviceState storage state = devices[device];
        require(state.firmwareVersion > 0, "Device not registered");
        require(!state.awaitingConfirmation, "Update pending");
        require(windowDuration >= MIN_WINDOW_DURATION, "Window too short");

        FirmwareMetadata storage fw = firmwares[targetVersion];
        require(fw.checksum != bytes32(0), "Firmware not registered");
        require(state.firmwareVersion >= fw.minVersion, "Current version too old");
        require(fw.deployedCount < fw.maxDevices, "Max deployments reached");

        // Check cooldown from last update
        uint256 lastUpdate = deviceUpdateTimestamps[device][state.firmwareVersion];
        require(
            block.timestamp >= lastUpdate + globalUpdateCooldown,
            "Cooldown active"
        );

        state.pendingVersion = targetVersion;
        state.updateWindowStart = windowStart;
        state.updateWindowDuration = windowDuration;
        state.awaitingConfirmation = true;
        state.retryCount = 0;

        emit FirmwareScheduled(device, targetVersion);
    }

    function heartbeat() external onlyRegisteredDevice {
        devices[msg.sender].lastHeartbeat = block.timestamp;
        emit DeviceHeartbeat(msg.sender, block.timestamp);
    }

    /**
     * @notice Device confirms successful firmware update (async callback pattern)
     * @dev The device calls this after applying the firmware update
     *      This implements the "await" confirmation of the async update process
     */
    function confirmUpdate() external onlyRegisteredDevice {
        DeviceState storage state = devices[msg.sender];
        require(state.awaitingConfirmation, "No pending update");
        require(
            block.timestamp >= state.updateWindowStart &&
            block.timestamp <= state.updateWindowStart + state.updateWindowDuration,
            "Outside update window"
        );

        uint256 targetVersion = state.pendingVersion;
        FirmwareMetadata storage fw = firmwares[targetVersion];

        fw.deployedCount += 1;
        deviceUpdateTimestamps[msg.sender][targetVersion] = block.timestamp;

        state.firmwareVersion = targetVersion;
        state.pendingVersion = 0;
        state.awaitingConfirmation = false;
        state.lastHeartbeat = block.timestamp;

        emit FirmwareConfirmed(msg.sender, targetVersion);
    }

    /**
     * @notice Computes the effective security level delta between firmware versions
     * @dev Used by the rollback eligibility check to determine if rollback is safe
     * @param currentVersion The device's current firmware version
     * @param targetVersion The version to potentially roll back to
     * @return delta The absolute security level difference
     */
    function computeVersionDelta(
        uint256 currentVersion,
        uint256 targetVersion
    ) internal pure returns (uint256 delta) {
        // Compute distance between versions for security assessment
        // Both versions are guaranteed > 0 by registration checks
        delta = currentVersion - targetVersion;
    }

    /**
     * @notice Allows a device to roll back to a previous firmware version
     * @dev Rollback is only allowed within the grace period and if the version
     *      delta is within acceptable bounds (max 2 major versions back)
     */
    function rollbackFirmware(uint256 previousVersion) external onlyRegisteredDevice {
        DeviceState storage state = devices[msg.sender];
        require(!state.awaitingConfirmation, "Update in progress");
        require(previousVersion > 0, "Invalid version");

        // Verify the device was previously on this version
        uint256 previousTimestamp = deviceUpdateTimestamps[msg.sender][previousVersion];
        require(previousTimestamp > 0, "Never had this version");

        FirmwareMetadata storage currentFw = firmwares[state.firmwareVersion];
        require(
            block.timestamp <= previousTimestamp + currentFw.rollbackGracePeriod,
            "Grace period expired"
        );

        // Security check: only allow rollback within 2 major versions
        uint256 versionGap = computeVersionDelta(state.firmwareVersion, previousVersion);
        require(versionGap <= 2, "Rollback too far");

        uint256 oldVersion = state.firmwareVersion;

        // Decrement deployed count for current version
        FirmwareMetadata storage oldFw = firmwares[oldVersion];
        oldFw.deployedCount -= 1;

        state.firmwareVersion = previousVersion;
        state.lastHeartbeat = block.timestamp;
        deviceUpdateTimestamps[msg.sender][previousVersion] = block.timestamp;

        emit FirmwareRolledBack(msg.sender, oldVersion, previousVersion);
    }

    /**
     * @notice Admin can force-expire a stale update if device missed its window
     */
    function expireUpdate(address device) external onlyAdmin {
        DeviceState storage state = devices[device];
        require(state.awaitingConfirmation, "No pending update");
        require(
            block.timestamp > state.updateWindowStart + state.updateWindowDuration,
            "Window still active"
        );

        state.retryCount += 1;
        if (state.retryCount >= MAX_RETRY) {
            state.awaitingConfirmation = false;
            state.pendingVersion = 0;
            state.retryCount = 0;
        } else {
            // Reset window for retry
            state.updateWindowStart = block.timestamp;
        }
    }

    function getDeviceInfo(address device) external view returns (
        uint256 firmwareVersion,
        bool hasPendingUpdate,
        uint256 pendingVersion,
        bool isOnline
    ) {
        DeviceState storage state = devices[device];
        firmwareVersion = state.firmwareVersion;
        hasPendingUpdate = state.awaitingConfirmation;
        pendingVersion = state.pendingVersion;
        isOnline = (block.timestamp - state.lastHeartbeat) <= HEARTBEAT_TIMEOUT;
    }
}
